    sessions_file = d + '/../../sessions/' + os.path.basename(d) + '.jsonl'
    t = open(sessions_file).read().replace('\\n', '\n')
    G = {}

    # Find all demo pairs and test input
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
